const rowsOf = (node) => { try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; } };
const activeClients = () => rowsOf('Read Clients').filter((c) => c.client_id && String(c.status || '').toLowerCase() === 'active');
const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const daysAgo = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 864e5); };

const cfg = $('Config').first().json;
const clients = activeClients().filter((c) => /social|content/i.test(c.services || ''));
const content = rowsOf('Read Content');
const metrics = rowsOf('Read Metrics');
const week_of = $now.plus({ weeks: 1 }).startOf('week').toISODate(); // next Monday, in the workflow's timezone
const post = { type: 'object', additionalProperties: false, required: ['channel', 'day', 'hook', 'body', 'cta', 'hashtags', 'visual_brief'],
  properties: { channel: { type: 'string', enum: ['linkedin', 'instagram', 'x', 'facebook', 'tiktok'] }, day: { type: 'string', enum: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] },
    hook: { type: 'string' }, body: { type: 'string' }, cta: { type: 'string' }, hashtags: { type: 'array', items: { type: 'string' } },
    visual_brief: { type: 'string', description: 'What the designer should create for this post' } } };
const schema = { type: 'object', additionalProperties: false, required: ['theme_of_week', 'posts'],
  properties: { theme_of_week: { type: 'string' }, posts: { type: 'array', items: post } } };
return clients.map((c) => {
  const past = content.filter((r) => r.client_id === c.client_id).slice(-20).map((r) => r.hook);
  const latest = metrics.filter((m) => m.client_id === c.client_id).sort((a, b) => String(b.month).localeCompare(String(a.month)))[0];
  return { json: { client_id: c.client_id, client_name: c.client_name, week_of, brain: {
    skill: 'social', caller: 'Content Factory', client: c.client_name, effort: 'medium', max_tokens: 10000, schema,
    context: { client: c.client_name, website: c.website, audience: c.audience, brand_voice: c.brand_voice, goals: c.goals,
      services: c.services, last_month_performance: latest ? latest.headline : 'no report yet', hooks_already_used: past },
    task: `Write ${cfg.posts_per_client} social posts for ${c.client_name} for the week of ${week_of}. Choose channels that fit the audience (B2B usually LinkedIn-first). Mix formats: insight, story, proof, and one direct offer. Every hook must be new (see hooks_already_used). Match the brand voice exactly, keep claims verifiable, and spread posts across different days.`,
  } } };
});

const cfg = $('Config').first().json;
const dayIdx = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
const token = () => Array.from({ length: 24 }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');
const out = [];
for (const item of $input.all()) {
  const x = item.json;
  (x.ai?.posts || []).forEach((p, i) => {
    const d = DateTime.fromISO(x.week_of, { zone: $now.zone }).plus({ days: dayIdx[p.day] ?? i }).set({ hour: Number(cfg.post_hour) || 9, minute: 0 });
    out.push({ json: { id: `${x.client_id}-${x.week_of}-${i + 1}`, token: token(), client_id: x.client_id, client_name: x.client_name,
      week_of: x.week_of, channel: p.channel, publish_at: d.toUTC().toISO(), hook: p.hook, body: p.body, cta: p.cta,
      hashtags: (p.hashtags || []).map((h) => (h.startsWith('#') ? h : `#${h}`)).join(' '), visual_brief: p.visual_brief,
      media_url: '', status: 'Pending approval', reviewed_at: '', ayrshare_id: '' } });
  });
}
return out;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const li = (arr) => (arr || []).map((t) => `<li style="margin:0 0 6px">${esc(t)}</li>`).join('');
const card = (title, inner) => `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:18px 20px;margin:0 0 16px"><h3 style="margin:0 0 10px;font-size:16px;color:#111827">${esc(title)}</h3>${inner}</div>`;
const shell = (title, sub, inner) => `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;color:#1f2937;line-height:1.5"><div style="padding:24px 0 8px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6b7280">${esc(sub)}</div><h1 style="margin:4px 0 0;font-size:24px;color:#111827">${esc(title)}</h1></div>${inner}</div>`;
const pct = (v) => (v === null || v === undefined || Number.isNaN(v)) ? 'n/a' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`;

const rowsOf = (node) => { try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; } };
const activeClients = () => rowsOf('Read Clients').filter((c) => c.client_id && String(c.status || '').toLowerCase() === 'active');
const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const daysAgo = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 864e5); };

const cfg = $('Config').first().json;
const base = String(cfg.webhook_base_url).replace(/\/$/, '');
const clients = Object.fromEntries(activeClients().map((c) => [c.client_id, c]));
const byClient = {};
for (const { json: r } of $('Explode Posts').all()) (byClient[r.client_id] ||= []).push(r);
const themes = Object.fromEntries($('Brain: Draft Posts').all().map((i) => [i.json.client_id, i.json.ai?.theme_of_week || '']));
return Object.entries(byClient).map(([cid, posts]) => {
  const c = clients[cid] || {};
  const btn = (p, d, label, color) => `<a href="${base}/webhook/content-review?id=${encodeURIComponent(p.id)}&t=${p.token}&d=${d}" style="display:inline-block;margin-right:8px;background:${color};color:#fff;padding:8px 14px;border-radius:6px;text-decoration:none;font-size:13px;font-weight:600">${label}</a>`;
  const cards = posts.map((p) => card(`${new Date(p.publish_at).toDateString()} · ${p.channel}`,
    `<p style="margin:0 0 8px;font-weight:600">${esc(p.hook)}</p><p style="margin:0 0 8px;white-space:pre-wrap">${esc(p.body)}</p><p style="margin:0 0 8px">${esc(p.cta)}</p><p style="margin:0 0 12px;color:#4f46e5;font-size:13px">${esc(p.hashtags)}</p><p style="margin:0 0 12px;font-size:12px;color:#6b7280">Visual: ${esc(p.visual_brief)}</p>${btn(p, 'approve', 'Approve', '#059669')}${btn(p, 'changes', 'Request changes', '#6b7280')}`)).join('');
  const html = shell(`Your content for the week of ${posts[0].week_of}`, `${cfg.agency_name} · ${themes[cid] || 'weekly content'}`,
    `<p>Hi ${esc(String(c.contact_name || '').split(' ')[0] || 'there')}, here are next week's posts. Approve each one with a click. Anything you don't approve won't be published.</p>${cards}`);
  return { json: { client_id: cid, client_name: posts[0].client_name, to: c.contact_email, cc: c.account_manager_email || '', count: posts.length,
    subject: `Approve next week's ${posts.length} posts: ${posts[0].client_name}`, html } };
}).filter((e) => e.json.to);
